-- Step 1 of 4: add accounts.region as NULLABLE, no default.
-- Metadata-only in PostgreSQL (no table rewrite, no scan). Needs a brief ACCESS EXCLUSIVE
-- lock, so fail fast instead of queueing behind long transactions and blocking writers.
-- Reversible: yes (see .down.sql) until the backfill has written values.
-- Idempotent: IF NOT EXISTS.
SET lock_timeout = '3s';

ALTER TABLE accounts ADD COLUMN IF NOT EXISTS region text;

COMMENT ON COLUMN accounts.region IS
  'Account region code. Nullable during rollout; NOT NULL enforced by migration 0004. Value set: OPEN QUESTION (see return).';
